import{_ as t,o,c as d,a3 as n}from"./chunks/framework.C6R8kWFE.js";const g=JSON.parse('{"title":"多租户与版本","description":"","frontmatter":{},"headers":[],"relativePath":"backend/multi-tenancy.md","filePath":"backend/multi-tenancy.md","lastUpdated":1790294583000}'),c={name:"backend/multi-tenancy.md"};function a(r,e,i,l,s,u){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="多租户与版本" tabindex="-1">多租户与版本 <a class="header-anchor" href="#多租户与版本" aria-label="Permalink to &quot;多租户与版本&quot;">​</a></h1><p>XiHan.BasicApp 是一套 <strong>企业级通用中后台内核</strong>：一份代码、一套部署，同时承载多个互不可见的租户（企业客户），并以**版本（Edition）**作为订阅售卖与功能门控的单元。本页讲清楚隔离怎么落地、登录后落到哪里、超级管理员如何跨租户运维、版本白名单如何在运行时门控权限，以及请求如何解析到租户上下文。</p><p>权限码、数据范围、字段脱敏等细节见 <a href="./permission">权限模型</a>；框架层的租户上下文、解析链与存储见 <a href="https://framework.docs.xihanfun.com/packages/multitenancy" target="_blank" rel="noreferrer">XiHan.Framework.MultiTenancy</a>。本页聚焦 BasicApp 应用层的租户与版本机制。</p><h2 id="隔离模型-字段级隔离-tenantid-0-约定" tabindex="-1">隔离模型：字段级隔离 + <code>TenantId=0</code> 约定 <a class="header-anchor" href="#隔离模型-字段级隔离-tenantid-0-约定" aria-label="Permalink to &quot;隔离模型：字段级隔离 + `TenantId=0` 约定&quot;">​</a></h2><p>BasicApp 默认走<strong>字段级隔离（Field）</strong>：所有业务实体继承自 <code>BasicApp*</code> 实体基类族（<code>BasicAppEntity</code> / <code>BasicAppCreationEntity</code> / <code>BasicAppFullAuditedEntity</code> / <code>BasicAppAggregateRoot</code> 等，底层是框架的 <code>SugarMultiTenant*&lt;long&gt;</code>），带一个 <code>TenantId</code> 列，查询按当前租户上下文自动过滤，无需业务代码手动拼条件。</p><p>隔离模式由 <code>SysTenant.IsolationMode</code>（<code>TenantIsolationMode</code>）声明，支持三种，<code>SysTenant</code> 还预留了独立库连接串等字段：</p><table tabindex="0"><thead><tr><th>模式</th><th>含义</th></tr></thead><tbody><tr><td><code>Field</code>（默认）</td><td>同库同表，靠 <code>TenantId</code> 列区分租户数据</td></tr><tr><td><code>Database</code></td><td>每租户独立数据库（<code>ConnectionString</code> 加密存储；先 <code>InitializeDatabase</code> 建库建表，再 <code>InitializeTenantAdmin</code> 开通管理员，见下文「库隔离：平台库是目录库」）</td></tr><tr><td><code>Schema</code></td><td>同库不同 Schema（尚未实装：创建时拒绝；<code>SaasTenantConnectionProvider</code> 解析到该模式直接抛异常 fail-closed，拒绝退化为行隔离）</td></tr></tbody></table><p>隔离模式创建时定下、之后不能修改（不在更新契约里）：数据按创建时的模式落库，改模式等于迁移数据，不是改一个字段。</p><h3 id="框架层-long-null-与应用层-tenantid-0-的关系" tabindex="-1">框架层 <code>long?</code>/null 与应用层 <code>TenantId=0</code> 的关系 <a class="header-anchor" href="#框架层-long-null-与应用层-tenantid-0-的关系" aria-label="Permalink to &quot;框架层 `long?`/null 与应用层 `TenantId=0` 的关系&quot;">​</a></h3><p>这是理解本系统隔离的关键，两层用<strong>不同的空值语义</strong>表达&quot;全局/无租户&quot;：</p><ul><li><strong>框架层</strong>：<code>ICurrentTenant.Id</code> 是 <code>long?</code>。<code>null</code> 与 <code>0</code> 同义，都表示<strong>平台，也就是 0 号租户</strong>。平台和任何一个租户一样只看、只写自己的数据：读只看 <code>TenantId=0</code> 的行，写只落 / 只改 <code>TenantId=0</code> 的行——不存在「没有租户上下文就看全部、写全部」的口径。</li><li><strong>BasicApp 应用层落库约定</strong>（见 <code>BasicAppEntity</code> 注释）：平台级/全局记录统一落 <strong><code>TenantId=0</code></strong>（&quot;平台租户&quot;占位），<strong>不得用 NULL</strong>；业务租户 Id 从 1 开始分配，0 号租户由平台保留。</li></ul><p>二者衔接的规则：</p><ul><li>平台判定统一以 <code>currentTenant.IsPlatformOperation()</code> 为准，其实现就是 <code>Id is null or 0</code>（见 <code>CurrentTenantPlatformExtensions</code>）。</li><li>查询&quot;全局 + 私有&quot;合并时用 <code>WHERE TenantId IN (0, {currentTenantId})</code>。授权快照构建即按此规则：绑定行按 <code>TenantId == 当前租户 || TenantId == 0</code> 生效，平台态（无上下文）则仅 <code>TenantId=0</code> 的全局绑定生效，防止多租户成员在平台态聚合出跨租户权限。</li><li>如需 <code>IsGlobal</code> 语义，实体在 Expand 里以只读派生属性 <code>IsGlobal =&gt; TenantId == 0</code> 暴露，<strong>不落库</strong>（避免与 <code>TenantId</code> 漂移）。</li><li>只有平台才允许维护 <code>TenantId=0</code> 的全局模板（菜单/权限/角色/版本等）；租户态（<code>Id&gt;0</code>）对全局模板一律拒绝写入，避免某租户改动波及所有租户。平台同样不能直接改写租户的行。</li><li>平台与租户各自独有的运行数据（会话、令牌、授权码、导出任务、邮件短信、导入记录、任务调度与各类日志）与租户业务数据（部门、岗位、部门归属、文件、审批、权限申请，以及代码生成器产出的业务实体）实现 <code>IStrictMultiTenantEntity</code>：租户态只看本租户行，不读共享平台行。</li></ul><blockquote><p>服务层通过框架注入自动写入 <code>TenantId</code>，业务代码禁止直接操纵。跨租户只走显式通道：跨租户读取用仓储的 <code>...IgnoreTenantAsync</code>（内部 <code>CreateNoTenantQueryable()</code>）或查询上的 <code>.ClearTenantFilter()</code>；写某个租户的数据用 <code>ICurrentTenant.Change(tenantId)</code> 切入该租户，<code>using</code> 作用域结束自动恢复；账号域数据写在账号注册地——新增经 <code>IAccountScope.EnterAsync(userId)</code> 切入注册地，个人中心更新自己已有的行可用 <code>TenantWriteGuard.Suppress()</code>（只放宽更新与删除，不放宽新增）。后台逐租户维护用 <code>ITenantDataScopeRunner</code> 依次切入平台与每个数据可达的租户。</p></blockquote><h2 id="登录与落点-邮箱全局唯一-先登录后选租户" tabindex="-1">登录与落点：邮箱全局唯一，先登录后选租户 <a class="header-anchor" href="#登录与落点-邮箱全局唯一-先登录后选租户" aria-label="Permalink to &quot;登录与落点：邮箱全局唯一，先登录后选租户&quot;">​</a></h2><p>BasicApp 采用<strong>先登录、后定上下文</strong>：登录页不选择租户，统一在平台（<code>_currentTenant.Change(null)</code>）完成身份认证，成功后由服务端决定落点——登录后总是落在一个上下文里（平台，或一个租户）。</p><ul><li><strong>邮箱是全平台唯一的登录身份标识</strong>。注册、开通租户管理员、找回密码都强制校验邮箱且全局唯一（<code>ExistsEmailGloballyAsync</code>）。平台账号也可用用户名登录。</li><li>支持密码登录、邮箱验证码登录、第三方（OAuth）登录，均在平台态定位用户后走统一落点逻辑（<code>IssueLoginTokenWithLandingAsync</code>）。</li></ul><h3 id="落点策略" tabindex="-1">落点策略 <a class="header-anchor" href="#落点策略" aria-label="Permalink to &quot;落点策略&quot;">​</a></h3><p>平台是 0 号租户，只对<strong>平台账号</strong>（<code>SysUser.TenantId=0</code>）开放。落点由 <code>ResolveLoginLandingAsync</code> 决定：</p><table tabindex="0"><thead><tr><th>账号</th><th>落点</th></tr></thead><tbody><tr><td>平台账号</td><td>平台</td></tr><tr><td>租户账号</td><td>最近进入过的可进入租户 → 归属租户 → 第一个可进入的租户（<code>LoginLandingPolicy</code>）</td></tr><tr><td>租户账号且一个可进入的租户都没有</td><td>拒绝登录，并说明是没有有效成员关系，还是所在租户均不可进入</td></tr></tbody></table><p><strong>可进入的租户</strong>只有一个口径（<code>IAuthContextQueryService.GetAccessibleTenantsAsync</code>）：有效成员关系（已接受、有效、在生效期内）∩ 可进入的租户（<code>AvailableTenantSpecification</code>：正常、已完成初始化、未删除、未过期）。登录落点、切换租户、控制中心的可切换列表都用它。成员关系的最近进入时间（<code>LastActiveTime</code>）在登录与切换时回写，决定下次登录落点。</p><p>签发的令牌只在进入租户时带 <code>TenantId</code> claim，平台不带。</p><h3 id="随时切换租户" tabindex="-1">随时切换租户 <a class="header-anchor" href="#随时切换租户" aria-label="Permalink to &quot;随时切换租户&quot;">​</a></h3><p>登录后通过页头的上下文标识进控制中心，经 <code>SwitchTenantAsync</code>（<code>api/Auth</code>）切换（类似 GitHub 切换 Org）：</p><ul><li>目标 <code>TenantId</code> 归一：<code>null</code> 或 <code>&lt;=0</code> 表示平台。</li><li>进入租户：必须在&quot;可进入的租户&quot;里，<strong>超管也不例外</strong>——平台账号要进某个租户，同样须先成为它的成员（如支持人员入驻）。</li><li>进入平台：只有平台账号可以。</li><li><strong>切换即换会话</strong>：会话属于它所在的上下文（<code>SysUserSession.TenantId</code> 只插入不更新）。切换时吊销当前会话、在目标上下文新建一条续接会话（沿用设备与登录时间，不是新登录、不发登录通知），旧访问令牌与刷新令牌经会话闸门随即失效；会话标识因此全局唯一（<code>UX_{table}_UsSeId</code>）。</li><li>在目标上下文内<strong>重建授权快照并签发新令牌</strong>，权限随目标上下文实时重算。</li><li>结束模仿登录回到发起人的原会话，只在原会话上重签令牌（原会话本就在发起时的上下文里）。</li></ul><p>前端切换后整页重建：清掉本地用户信息与标签页、断开 SignalR；路由守卫在整页加载时把用户信息与权限一起重取，平台 / 租户标识不会沿用切换前的旧值。可切换的租户列表由 <code>GetMyAvailableTenantsAsync</code> 提供，与切换同一口径；前端用 <code>TenantSwitcherDto</code> 渲染。</p><h2 id="成员关系-systenantuser" tabindex="-1">成员关系：<code>SysTenantUser</code> <a class="header-anchor" href="#成员关系-systenantuser" aria-label="Permalink to &quot;成员关系：`SysTenantUser`&quot;">​</a></h2><p>&quot;谁能进入哪个租户&quot;由 <code>SysTenantUser</code>（<code>Sys_Tenant_User</code>）承载——它是 用户 × 租户 的多对多成员表，是跨租户协作与平台运维统一建模的入口。语义上区分：</p><ul><li><code>SysUser.TenantId</code> = 用户主账号的归属租户（注册地）</li><li><code>SysTenantUser.TenantId</code> = 用户拥有成员身份的租户（含主租户 + 外部协作租户）</li></ul><p>所有租户访问（含主属）都统一走本表，鉴权路径一致。成员关系是<strong>严格租户隔离</strong>实体：租户里只看得到本租户的成员行，跨租户读取（如登录时取用户的全部成员关系）走显式通道。关键字段：</p><ul><li><code>MemberType</code>（<code>TenantMemberType</code>）：<code>Owner</code> / <code>Admin</code> / <code>Member</code> / <code>External</code> / <code>Guest</code> / <code>Consultant</code> / <code>PlatformAdmin</code>。 <ul><li>注意：<code>MemberType</code> 表达&quot;成员身份类型&quot;而非&quot;权限级别&quot;，<strong>服务层禁止用它直接鉴权</strong>（如 <code>if MemberType==Admin</code>），必须走 RBAC 权限链；它只用于成员列表分类、邀请流程控制、<code>PlatformAdmin</code> 创建校验。</li></ul></li><li><code>InviteStatus</code>（<code>TenantMemberInviteStatus</code>）：<code>Pending → Accepted / Rejected / Revoked / Expired</code>。仅 <code>Accepted</code> 且 <code>Status=Valid</code> 且当前时间在生效/失效区间内的成员关系才可用于鉴权。</li><li><code>EffectiveTime</code> / <code>ExpirationTime</code>：外部协作者/访客常用的时效控制。</li><li><strong>成员关系上的授权由所在租户维护</strong>：角色、直授权限、部门、数据范围（成员覆盖 <code>DataScopeOverride</code> 挂在成员关系上）、ABAC 条件、字段级安全、约束、委托、申请都作用于「本租户的成员」；支持成员（<code>PlatformAdmin</code>，平台人员入驻）也一样——平台看不到也写不了租户的授权数据，他们在租户里能做什么由这个租户决定。</li></ul><h2 id="账号域-注册地租户戳-严格隔离" tabindex="-1">账号域：注册地租户戳 + 严格隔离 <a class="header-anchor" href="#账号域-注册地租户戳-严格隔离" aria-label="Permalink to &quot;账号域：注册地租户戳 + 严格隔离&quot;">​</a></h2><p>账号是身份层数据，不是某个租户的业务数据。<code>SysUser</code>、<code>SysUserSecurity</code>、<code>SysUserSetting</code>、<code>SysUserNotificationPreference</code>、<code>SysUserApiCredential</code>、<code>SysExternalLogin</code>、<code>SysPasswordHistory</code> 实现 <code>IStrictMultiTenantEntity</code>，<code>TenantId</code> 固定为注册地（平台账号为 0）：</p><ul><li><strong>按主键跨租户读</strong>：账号、安全记录、个人设置等按用户主键走 <code>...IgnoreTenantAsync</code> / <code>CreateNoTenantQueryable()</code> 读取，展示别人的名字、取当前用户自己的资料都不依赖当前上下文。</li><li><strong>写在注册地</strong>：外部成员在别的租户里改设置、建凭据、改密码，行照样落回注册地（<code>IAccountScope</code>、密码历史切入 <code>user.TenantId</code> 写入）。</li><li><strong>看得见谁由上下文决定</strong>（<code>IUserDirectory</code>）：平台里是平台账号；租户里是本租户已接受的成员，含注册在别处的外部成员与入驻的平台人员。用户列表、详情、选择项、聊天候选人、&quot;全员&quot;通知都走同一个目录，列表项带 <code>IsExternalMember</code>。</li><li><strong>身份类操作只对本地账号</strong>：资料、状态、锁定、密码、双因素、登录策略、下线全部会话、删除只对注册在当前上下文的账号开放；外部成员给出明确原因（&quot;由其注册地租户维护&quot;），在这里只能管理它在本租户的角色、权限、部门与数据范围。前端对外部成员隐藏账号级操作，编辑弹窗只提交角色与部门。</li><li><strong>平台建的是平台账号</strong>：平台里建账号不写成员关系、不占席位；租户里建账号占一个席位并成为本租户已接受的成员。</li><li><strong>删除 / 停用是账号级操作</strong>：账号是任何一个租户的有效所有者都不能直接删除或停用；删除时逐租户切入，作废它在每个租户的成员关系。</li></ul><h2 id="租户所有者-一名、始终有效、由平台移交" tabindex="-1">租户所有者：一名、始终有效、由平台移交 <a class="header-anchor" href="#租户所有者-一名、始终有效、由平台移交" aria-label="Permalink to &quot;租户所有者：一名、始终有效、由平台移交&quot;">​</a></h2><p>每个租户有且只有一名所有者，是开通管理员时产生的那位（<code>MemberType=Owner</code>，持有本租户的 <code>tenant_owner</code> 系统角色）：</p><ul><li><strong>权限随套餐</strong>：<code>tenant_owner</code> 是租户里唯一的系统角色（<code>RoleType.System</code>、<code>TenantId=本租户</code>），不写授权行。授权快照让持有者拿到租户生效的全部权限，再经套餐门控收窄到白名单——套餐升降、新增权限码都即时反映，不用回头同步。它的数据范围是全部，所有者的成员关系上也不设覆盖。</li><li><strong>租户里改不动</strong>：系统角色的定义与成员只由系统流程维护——租户里不能编辑、停用、删除它，不能把它授给别人，也不能撤销或停用所有者手里那条绑定；角色选择项里不出现；<code>super_admin</code>、<code>tenant_owner</code> 两个编码保留，手工建不了同码角色。</li><li><strong>所有者关系始终有效</strong>：不能由租户指派（添加、邀请、改成员类型都不接受 <code>Owner</code>），不能撤销、停用、过期或退回未接受，也不能设生效期限；所有者账号不能被锁定、重置密码、停用或删除。</li><li><strong>所有权转移走平台</strong>：<code>TransferTenantOwner</code>（权限 <code>saas:tenant:transfer-owner</code>，平台侧）把所有者身份转给该租户的另一名成员——接任者须是已接受、有效、在生效期内的非支持成员；接任者成为所有者、拿到 <code>tenant_owner</code> 绑定、期限清空，原所有者改为管理员、这条绑定失效，其它角色原样保留。两人的授权快照随即失效。管理页在租户详情的「成员」页签里对可接任的成员给出「设为所有者」。</li></ul><h2 id="租户看自己的订阅" tabindex="-1">租户看自己的订阅 <a class="header-anchor" href="#租户看自己的订阅" aria-label="Permalink to &quot;租户看自己的订阅&quot;">​</a></h2><p>租户注册表与版本是平台数据，租户看不到租户列表；看自己的订阅走专门的只读接口 <code>TenantQuery/MySubscription</code>（权限 <code>saas:tenant-subscription:read</code>，租户侧，免费版起都在白名单里）：版本名称与说明、租户状态、到期时间，以及席位、存储的生效上限与已用量——与平台租户列表同一口径（<code>ITenantQuotaDomainService.GetQuotaSnapshotsAsync</code>）。管理端页面是「租户管理 → 我的订阅」，平台上下文里不出现。</p><h2 id="超级管理员-只在平台成立" tabindex="-1">超级管理员：只在平台成立 <a class="header-anchor" href="#超级管理员-只在平台成立" aria-label="Permalink to &quot;超级管理员：只在平台成立&quot;">​</a></h2><p>超级管理员（平台上的 <code>super_admin</code> 角色）是平台运营方账号，超管身份只在平台（0 号租户）成立：</p><ul><li><strong>平台里通配</strong>：授权快照带 <code>*</code>，外加平台生效的全部权限；平台不受套餐门控。</li><li><strong>进了业务租户就只是那个租户的成员</strong>：平台的超管绑定不带进任何租户，快照按目标租户里的角色、直授与委托重建，再经套餐门控；在租户里没有角色就没有权限。<code>ISuperAdminProtector.IsCurrentUserSuperAdmin</code> 同口径——业务租户里恒为 <code>false</code>，各处&quot;超管豁免&quot;只在平台生效。</li><li>替租户排查问题走<strong>模仿登录</strong>（以目标租户成员身份操作、全程留痕），不靠超管身份直接改租户数据。平台里发起时先选范围：平台账号，或某个租户（再从该租户的成员里选人）；租户里只能选本租户成员。成员检索同时匹配成员显示名与账号的用户名 / 昵称 / 姓名 / 邮箱。</li></ul><h2 id="权限作用侧-平台-租户-两侧" tabindex="-1">权限作用侧：平台 / 租户 / 两侧 <a class="header-anchor" href="#权限作用侧-平台-租户-两侧" aria-label="Permalink to &quot;权限作用侧：平台 / 租户 / 两侧&quot;">​</a></h2><p>权限目录的每条权限都声明<strong>作用侧</strong>（<code>SysPermission.Side</code>，<code>PermissionSide</code> 标志枚举）：</p><table tabindex="0"><thead><tr><th>作用侧</th><th>值</th><th>在哪生效</th><th>典型权限</th></tr></thead><tbody><tr><td><code>Platform</code></td><td>1</td><td>只在平台</td><td>租户目录、套餐、权限/资源/菜单目录维护、缓存、服务器、任务调度、AI（模型提供方、提示词、助手、知识库）、代码生成、Telegram 机器人、全局编号/打印模板管理、跨租户模仿</td></tr><tr><td><code>Tenant</code></td><td>2</td><td>只在业务租户</td><td>租户成员维护、部门、岗位、成员数据范围、审批、工作流</td></tr><tr><td><code>Both</code></td><td>3</td><td>两侧都生效</td><td>用户、角色、授权、角色数据范围（平台只设全局角色模板的档位）、日志、配置、字典、消息等</td></tr></tbody></table><ul><li><strong>声明在代码里</strong>：Saas 权限由 <code>SaasPermissionDefinitions</code> 的分组声明（条目可单独覆盖），其它模块由各自的权限种子声明；种子每次启动把作用侧同步到库里。后台新建权限必须选作用侧，未声明（0）的权限在任何上下文都不生效。</li><li><strong>生效 = 当前上下文的授权绑定 ∩ 作用侧 ∩ 套餐白名单（仅业务租户）</strong>。作用侧不含当前上下文的权限码随授权快照下发（<code>ContextDeniedCodes</code>），鉴权、菜单与按钮先于通配判定拒绝它们——平台超管的 <code>*</code> 也放不出租户侧权限。</li><li><strong>授权绑定只在所属上下文生效</strong>：<code>SysUserRole</code> / <code>SysUserPermission</code> / <code>SysPermissionDelegation</code> / <code>SysUserDepartment</code> / <code>SysUserDataScope</code> 是严格租户隔离实体，平台的绑定不进租户，租户的绑定也不进平台。</li><li><strong>授权界面按上下文列可授权限</strong>：业务租户里只列、也只允许授出租户能生效的权限（租户侧与两侧），写路径同口径拒绝；平台列全部，授权穿梭框标出单侧权限。分配角色不按作用侧拦（角色上的平台侧权限在租户里本就不生效）。</li></ul><h2 id="全局模板-平台下发-租户只读或覆盖" tabindex="-1">全局模板：平台下发，租户只读或覆盖 <a class="header-anchor" href="#全局模板-平台下发-租户只读或覆盖" aria-label="Permalink to &quot;全局模板：平台下发，租户只读或覆盖&quot;">​</a></h2><p><code>TenantId=0</code> 的模板行（全局角色、参数配置、字典等）读共享：租户看得见、改不了，改写与删除只在平台。按能否被租户覆盖分两种：</p><table tabindex="0"><thead><tr><th>类型</th><th>实体</th><th>租户能做什么</th><th>判重</th></tr></thead><tbody><tr><td>可覆盖型</td><td>参数配置、消息模板、编号规则、打印模板</td><td>建同键的自己的行，读取时租户优先</td><td>只在本上下文内判重</td></tr><tr><td>不可覆盖型</td><td>全局角色、字典</td><td>引用或分配；要改就新建自己的角色 / 字典</td><td>字典编码在「全局 + 本租户」里唯一</td></tr></tbody></table><ul><li><strong>全局角色</strong>：可以分配给本租户成员、被本租户角色继承；但它的授权、授权条件、数据范围、继承关系、启停与删除只在平台维护，租户不能往上叠加自己的授权。</li><li><strong>字典</strong>：字典项与所属字典同在一个上下文，全局字典的项只在平台维护；租户需要自己的选项就新建字典。平台建全局字典时要看所有租户，某个租户已用了这个编码就不能再建（否则会在那个租户里重名）。</li><li><strong>AI</strong>：模型提供方、提示词、助手只在平台维护；提示词与助手是平台下发的目录，租户里可用不可改（运行时按编码读提示词、按聊天权限用助手）；知识库是平台私有数据，严格隔离。</li><li><strong>工作流</strong>：租户侧功能，定义、实例、节点、书签严格隔离；定时器跨租户取到期书签后逐租户切入执行。</li><li><strong>平台删除全局行看所有租户</strong>：全局角色被租户成员持有或被租户角色继承、全局字典还有字典项时不能删除——这些行平台自己看不见，要跨租户检查（<code>ISaasRepository.AnyIgnoreTenantAsync</code>）。</li></ul><h2 id="带密钥的配置-严格隔离-平台服务显式回退" tabindex="-1">带密钥的配置：严格隔离，平台服务显式回退 <a class="header-anchor" href="#带密钥的配置-严格隔离-平台服务显式回退" aria-label="Permalink to &quot;带密钥的配置：严格隔离，平台服务显式回退&quot;">​</a></h2><p>存储、邮件、短信、机器人配置与 Telegram 机器人都带着密钥或凭证，实现 <code>IStrictMultiTenantEntity</code>：租户只看得见、只用得上自己的，平台的行对租户不可见。</p><table tabindex="0"><thead><tr><th>配置</th><th>租户未自配时</th></tr></thead><tbody><tr><td>邮件、短信</td><td>由平台默认代发（<code>CurrentThenPlatformAsync</code> 显式切到平台取默认）</td></tr><tr><td>对象存储</td><td>上传用平台默认；文件记下所用的存储配置（<code>SysFileStorage.StorageConfigId</code>），之后下载、删除、预签名都按它取凭证，换默认不影响既有文件</td></tr><tr><td>钉钉 / 飞书 / 企微机器人</td><td>不回退：租户的通知不能发进平台的群</td></tr><tr><td>Telegram</td><td>机器人由平台托管，只在平台维护与运行；机器人通知广播里的 Telegram 通道也只在平台生效</td></tr></tbody></table><p>平台删除存储配置时跨租户检查文件记录：平台默认存储可能被未自配的租户用着。文件记录在各租户自己的数据里，库隔离租户的在它自己的库里，检查逐库进行（见下文）。</p><h2 id="库隔离-平台库是目录库" tabindex="-1">库隔离：平台库是目录库 <a class="header-anchor" href="#库隔离-平台库是目录库" aria-label="Permalink to &quot;库隔离：平台库是目录库&quot;">​</a></h2><p>库隔离（<code>Database</code>）租户有自己的独立库，但不是所有数据都搬过去。平台库是<strong>目录库</strong>，实体标 <code>[PlatformDataSource]</code>（框架 <code>XiHan.Framework.Data.SqlSugar.Routing</code>）后固定落在这里——不管当前租户是否独立库，读写都按实体解析到平台库，建表也只在平台库建；行级租户过滤照常生效：</p><table tabindex="0"><thead><tr><th>落点</th><th>实体</th><th>为什么</th></tr></thead><tbody><tr><td>平台库</td><td>租户目录与套餐、权限/资源/操作/菜单目录、OAuth 应用</td><td>平台目录，所有租户共用</td></tr><tr><td>平台库</td><td>账号域、成员关系、会话、会话角色、OAuth 授权码与令牌</td><td>登录、令牌兑换、会话闸门在拿到租户之前就要定位；一个账号可以加入多个租户</td></tr><tr><td>平台库</td><td>角色、角色授权/继承/数据范围、用户角色/直授/数据范围、权限委托、授权条件、约束规则、字段安全</td><td>全局角色是读共享模板；平台跨租户检查引用、按全局角色找受影响的账号</td></tr><tr><td>平台库</td><td>参数配置、字典、消息模板、编号规则与分配、通知与收件箱</td><td>读共享（含租户自己的覆盖行）：租户要看得见平台的行</td></tr><tr><td>平台库</td><td>任务调度、Telegram、AI 维护（模型提供方、提示词、助手、知识库）、代码生成、打印模板</td><td>平台专属或平台下发</td></tr><tr><td>租户库</td><td>部门、岗位、部门归属、文件、审批、权限申请、各类日志、邮件短信、导出导入、带密钥的配置、用户统计、聊天、工作流、业务实体</td><td>租户自己的业务与运行数据，严格隔离</td></tr><tr><td>每个库各一份</td><td>版本与迁移台账（<code>SysVersion</code> / <code>SysMigrationHistory</code>）</td><td>记录的是这个库自己的结构版本</td></tr></tbody></table><p>两条规则由结构测试守着（<code>EntityPlacementTests</code>、<code>UniqueIndexTenantScopeTests</code>）：</p><ul><li><strong>租户库里只有严格隔离的数据。</strong> 读共享要让租户看见 <code>TenantId=0</code> 的平台行，平台行只在平台库；留在租户库的读共享实体在字段隔离与库隔离的租户里会看到不同的数据。</li><li><strong>全局唯一的实体在平台库。</strong> 唯一约束只在一个库里成立，邮箱、会话标识、令牌 JTI、<code>client_id</code> 这类全局唯一的东西分散到各库就管不住重复。</li></ul><p>使用上的约定：</p><ul><li><strong>访问实体按实体取连接。</strong> 仓储本来就这样；绕过仓储直接用客户端时写 <code>ISqlSugarClientResolver.GetClientForEntity&lt;T&gt;()</code>（种子里是 <code>DbClientFor&lt;T&gt;()</code>），<code>GetCurrentClient()</code> 只用于当前租户主库上的租户库实体和库级操作（健康检查、升级脚本）。</li><li><strong>平台跨租户扫租户库里的数据要逐库走</strong>：<code>ITenantDataScopeRunner.RunPerDatabaseAsync</code> / <code>AnyPerDatabaseAsync</code> 先在平台库（覆盖平台与全部字段隔离租户）清掉租户过滤查一次，再逐个切入已建库的库隔离租户查它自己的库。工作流到期书签、平台存储配置的引用检查、租户列表的存储用量都这样取。平台库里的实体（账号、会话、角色绑定）跨租户查一次即可。</li><li><strong>一个工作单元同时写平台库与独立库时不是原子的</strong>：每个连接各开一个本地事务，框架不提供跨库分布式事务。例如在库隔离租户里新建成员，账号与成员关系写平台库，部门归属写它自己的库。</li><li><strong>种子只播平台库</strong>（<code>[DataSeeding(Target = DbInitializationTarget.Platform)]</code>）：本应用的种子写的都是平台库实体，独立库初始化只建表。</li><li><strong>升级脚本在每个库上各跑一遍</strong>，独立库建好即登记为最新版本；改平台库表的语句要先判表存在，见 <code>UpdateScripts/README.md</code>。</li></ul><p>5.2.0 及更早版本开出来的库隔离租户，数据按旧口径整套落在独立库里（角色、授权、会话等也在）。升级到本版本后这些数据要搬到平台库，没有自动迁移——跨库搬数据不是一段 SQL 能完成的，需要按上表人工迁移后再启用。</p><h2 id="租户版本-edition-权限白名单-运行时门控" tabindex="-1">租户版本（Edition）：权限白名单 + 运行时门控 <a class="header-anchor" href="#租户版本-edition-权限白名单-运行时门控" aria-label="Permalink to &quot;租户版本（Edition）：权限白名单 + 运行时门控&quot;">​</a></h2><p>版本是<strong>订阅售卖单元 + 功能门控单元</strong>。三张表分工明确：</p><table tabindex="0"><thead><tr><th>实体</th><th>表</th><th>职责</th></tr></thead><tbody><tr><td><code>SysTenantEdition</code></td><td><code>Sys_Tenant_Edition</code></td><td>版本能做什么、卖多少（<code>EditionCode</code>/<code>Price</code>/<code>BillingPeriodMonths</code>/<code>UserLimit</code>/<code>StorageLimit</code>/<code>IsDefault</code>）</td></tr><tr><td><code>SysTenantEditionPermission</code></td><td><code>Sys_Tenant_Edition_Permission</code></td><td>版本 → 权限<strong>白名单</strong>映射（<code>EditionId</code> × <code>PermissionId</code>，唯一）</td></tr><tr><td><code>SysTenant.EditionId</code></td><td><code>Sys_Tenant</code></td><td>某租户订阅了哪个版本（<code>null</code> 时取 <code>IsDefault=true</code> 的默认版本）</td></tr></tbody></table><p>内置版本种子（<code>SaasEditionSeeder</code>）：<code>free</code>（免费/默认，只读+基础成员）、<code>basic</code>（+组织/用户/角色管理）、<code>pro</code>（+高级权限/审计/安全）、<code>enterprise</code>（租户能生效的全部权限、不限配额）。种子排在全部模块的权限目录之后，只在版本首次创建时连同白名单写入，之后由平台运营维护（改过的不覆盖、删掉的不补回）；后来新增的权限要进哪些版本，由运营授予或由对应版本的升级脚本写入。手写白名单里混进平台侧或不存在的权限码，种子直接报错。版本记录本身是平台级（<code>TenantId=0</code>）。</p><p>关键约束（见 <code>SysTenantEdition</code> 与领域服务）：</p><ul><li><code>EditionCode</code> 全局唯一，如 <code>free</code>/<code>basic</code>/<code>pro</code>/<code>enterprise</code>。</li><li>同一时刻仅一个 <code>IsDefault=true</code>；设默认时先清其它默认（<code>ClearDefaultEditionsAsync</code>），且默认版本必须处于启用状态、不能被直接取消或禁用。</li><li>版本白名单只能绑定<strong>平台级全局权限</strong>（<code>permission.IsGlobal</code>，即 <code>TenantId=0</code>），权限须启用，且作用侧必须含租户——平台侧权限进不了租户，绑到套餐上会被拒绝。</li></ul><h3 id="运行时门控-越白名单的权限被拒" tabindex="-1">运行时门控：越白名单的权限被拒 <a class="header-anchor" href="#运行时门控-越白名单的权限被拒" aria-label="Permalink to &quot;运行时门控：越白名单的权限被拒&quot;">​</a></h3><p>门控在 <code>AuthorizationSnapshotQueryService</code> 构建授权快照时叠加（<code>ApplyEditionGatingAsync</code>）——用户在某租户能生效的权限，被该租户所属版本的白名单<strong>收窄取交集</strong>：越出白名单的权限即便被授予，也不进入生效权限集，等同被拒。</p><p>门控<strong>失败即拒绝</strong>：</p><ul><li>只有平台（0 号租户）不门控；业务租户一律门控，超管身份在租户里不成立，没有例外。</li><li>租户未绑定版本、或版本白名单为空时，生效权限为空。</li><li>门控缓存不可用时直接查库，不因缓存故障放行。</li></ul><p>性能上，门控白名单走<strong>独立的版本门控缓存</strong>（<code>SaasEditionGateCacheItem</code>，缓存名 <code>SaasCacheNames.EditionGate</code> = <code>basicapp:saas:tenancy:edition-gate</code>，10 分钟 TTL），在 per-user 授权快照缓存<strong>之外</strong>按当前租户上下文叠加，避免切换租户后缓存串味，鉴权热路径不必每请求查库。版本白名单/租户换版的写路径会调 <code>InvalidateEditionGateAsync</code> 失效缓存（事务提交后生效）。</p><h3 id="开通-先建租户-再初始化管理员" tabindex="-1">开通：先建租户，再初始化管理员 <a class="header-anchor" href="#开通-先建租户-再初始化管理员" aria-label="Permalink to &quot;开通：先建租户，再初始化管理员&quot;">​</a></h3><p>任何隔离模式都分步开通，建租户不带管理员：</p><ol><li><strong>建租户</strong>：<code>CreateTenant</code> 写租户注册表；版本未指定则取默认版本（没有默认版本时保持未绑定，门控按未启用处理）。字段隔离租户建好即 <code>Configured</code>，库隔离租户是 <code>Pending</code>；</li><li><strong>初始化数据库（仅库隔离）</strong>：<code>InitializeDatabase</code> 建库、建表、登记升级基线，成功后 <code>Configured</code>（建库是 DDL，不能包在事务型工作单元里，所以是独立一步，可重复执行）；</li><li><strong>初始化管理员</strong>：<code>InitializeTenantAdmin</code> 一站式开通（<code>TenantProvisionDomainService.ProvisionTenantAdminAsync</code>）。只有已配置、还没有所有者的租户可以调用；列表与详情的 <code>HasOwner</code> 标出是否已开通。</li></ol><p>开通写的都是新租户的数据，切入该租户（<code>ICurrentTenant.Change(tenantId)</code>）写入，行的 <code>TenantId</code> 由作用域决定，不预置：</p><ol><li><strong>建管理员</strong>：创建 <code>SysUser</code>（校验邮箱全局唯一）+ <code>SysUserSecurity</code>（密码哈希）+ <code>SysTenantUser</code>（<code>MemberType=Owner</code>、<code>InviteStatus=Accepted</code>）；</li><li><strong>建所有者角色</strong>：<code>SysRole.CreateTenantOwnerRole()</code>——系统角色 <code>tenant_owner</code>、数据范围 <code>All</code>、成员上限 1，不写授权行；</li><li><strong>绑定</strong>：把管理员挂到所有者角色（<code>SysUserRole</code>）。</li></ol><p>于是开通管理员后即&quot;能登录、是所有者、拥有套餐范围内的全部权限&quot;，无需人工逐项授权；之后换套餐也不用补授权（见「租户所有者」）。管理页上字段隔离租户建好会接着弹出开通管理员；库隔离租户要先初始化数据库——开通时连带写的租户数据（日志等）在它自己的库里，库得先在，账号、成员关系、角色与授权本身在平台库。</p><h4 id="库隔离租户的库" tabindex="-1">库隔离租户的库 <a class="header-anchor" href="#库隔离租户的库" aria-label="Permalink to &quot;库隔离租户的库&quot;">​</a></h4><p><code>InitializeDatabase</code> 建的是这个租户<strong>一整套</strong>布局：主库，加上它按约定自带的模块库。主连接下配了 <code>ModuleDataSourceConfigs</code> 的模块（如 <code>Erp</code>），租户也会有一个对应的库，库名由租户主库名派生成 <code>{租户库名}_{模块名}</code>——租户库叫 <code>qqq</code>，就还会建一个 <code>qqq_Erp</code>。主连接那条模块连接串留空（该模块不分库）时租户同样不分，模块表落它自己的主库。</p><p>这条约定由框架实现（<code>XiHan:Data:SqlSugarCore:EnableTenantModuleDatabaseConvention</code>，默认开），应用侧不写代码、不加配置。含义是：<strong>租户声明了库隔离，它的数据就都在它自己的库里</strong>，不会有一部分悄悄落回公共模块库。要把某个租户的模块库指到别的机器上，在 <code>ISqlSugarTenantConnectionProvider</code> 里显式给出 <code>ModuleDataSourceConfigs</code> 即可，显式的优先。</p><p>账号定位是跨租户的身份层操作：登录在平台作用域按全局唯一邮箱显式跨租户定位账号（<code>GetByEmailGloballyAsync</code>），账号的安全信息在账号归属租户内读写（见上文「登录与落点」）；<code>ExistsEmailGloballyAsync</code> / <code>ExistsUserNameInTenantAsync</code> 自身切到平台作用域、显式跨租户执行，租户范围由入参显式落进 <code>WHERE</code>，不依赖当前上下文。</p><h3 id="降级自动回收越权授权" tabindex="-1">降级自动回收越权授权 <a class="header-anchor" href="#降级自动回收越权授权" aria-label="Permalink to &quot;降级自动回收越权授权&quot;">​</a></h3><p>当版本白名单<strong>收窄</strong>（撤销/停用某条版本权限映射），系统会<strong>自动回收该版本下各租户存量的越权授权</strong>（<code>ReconcileEditionTenantsAuthorizationAsync</code> → <code>ReconcileTenantAuthorizationWithEditionAsync</code>）：</p><ul><li>触发点：<code>RevokeTenantEditionPermissionAsync</code>（撤销）、<code>UpdateTenantEditionPermissionStatusAsync</code>（映射被置为非 <code>Valid</code>）。恢复为有效则无需回收。</li><li>回收动作：把该租户下<strong>超出白名单</strong>的 <code>SysRolePermission</code> / <code>SysUserPermission</code> 存量行置为 <code>Invalid</code> 并记 <code>ExpirationTime</code> 与回收原因（&quot;套餐变更回收：超出当前版本权限白名单&quot;）。</li><li>边界：只回收该租户<strong>自有</strong>绑定行（<code>TenantId=本租户</code>）；全局行（<code>TenantId=0</code>）属平台运维资产，不在回收范围。白名单为空时运行时已一律拒绝，存量绑定保留不回收，白名单恢复后随之恢复。</li></ul><blockquote><p>运行时门控（快照收窄）+ 降级回收（存量清理）是两道并行防线：前者保证越权权限当下不生效，后者把已落库的越权授权行物理失效，避免日后升级/门控放开后旧越权授权&quot;复活&quot;。</p></blockquote><h2 id="租户解析-请求如何落到租户上下文" tabindex="-1">租户解析：请求如何落到租户上下文 <a class="header-anchor" href="#租户解析-请求如何落到租户上下文" aria-label="Permalink to &quot;租户解析：请求如何落到租户上下文&quot;">​</a></h2><p>一次请求进入后，框架在 HTTP 管线里执行<strong>租户解析链</strong>（<code>XiHanTenantResolveMiddleware</code>，在 <code>XiHan.Framework.Web.Api</code>），把解析结果写入 <code>ICurrentTenant</code>。解析贡献者按顺序命中即止（<code>Handled=true</code> 短路）：</p><table tabindex="0"><thead><tr><th>顺序</th><th>贡献者</th><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td><code>CurrentUserTenantResolveContributor</code></td><td>已登录用户的 <code>TenantId</code>（来自 JWT claim）</td><td>首位插入，是主路径；已认证且带租户则据此解析</td></tr><tr><td>2</td><td><code>HeaderTenantResolveContributor</code></td><td>请求头 <code>X-Tenant-Id</code>（默认键含 <code>X-Tenant-Id</code>/<code>x-tenant-id</code>/<code>TenantId</code>）</td><td><code>EnableHeaderResolve</code> 默认开</td></tr><tr><td>3</td><td><code>QueryStringTenantResolveContributor</code></td><td>查询串 <code>tenantId</code> / <code>tenant</code></td><td><code>EnableQueryStringResolve</code> 默认开</td></tr></tbody></table><p>配置节 <code>XiHan:MultiTenancy:Resolve</code>（<code>XiHanTenantResolveOptions</code>）可调头/查询串键名、开关与 <code>FallbackTenant</code>。</p><p>对 BasicApp 而言，<strong>主路径是令牌里的 <code>TenantId</code></strong>：先登录后选租户，登录时按落点决定令牌是否带 <code>TenantId</code> claim（平台态不带），之后每次请求由 <code>CurrentUserTenantResolveContributor</code> 据此还原上下文；换租户则重新签发令牌。解析链的完整机制见 <a href="https://framework.docs.xihanfun.com/packages/multitenancy" target="_blank" rel="noreferrer">XiHan.Framework.MultiTenancy</a>。</p><h2 id="与权限的交叉点" tabindex="-1">与权限的交叉点 <a class="header-anchor" href="#与权限的交叉点" aria-label="Permalink to &quot;与权限的交叉点&quot;">​</a></h2><p>版本门控是租户维度对权限的<strong>再收窄</strong>，叠在 RBAC/ABAC 判定链之上。完整判定链（认证 → 租户解析 → RBAC → ABAC → 数据范围 → 字段脱敏）与权限码/数据范围/FLS 细节见 <a href="./permission">权限模型</a>。要点回顾：</p><ul><li>授权快照只取当前上下文的绑定行（严格租户隔离），按作用侧裁掉不在当前上下文生效的权限，业务租户里再与版本白名单取交集。</li><li>只有平台不受版本门控；超管的 <code>*</code> 只在平台成立。</li><li>版本白名单只挂平台级全局权限，且作用侧必须含租户。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./permission">权限模型</a>：RBAC + ABAC、权限码、数据范围、字段脱敏</li><li><a href="./introduction">系统架构</a>：租户解析在请求管道中的位置</li><li><a href="https://framework.docs.xihanfun.com/packages/multitenancy" target="_blank" rel="noreferrer">XiHan.Framework.MultiTenancy</a>：框架层租户上下文、解析链与存储</li></ul>',97)])])}const p=t(c,[["render",a]]);export{g as __pageData,p as default};
